export const ownershipHandovers = sqliteTable(
  "ownership_handovers",
  {
    id: idColumn(),
    orgId: text("org_id").notNull(),
    fromUserId: text("from_user_id").notNull(),
    toUserId: text("to_user_id").notNull(),
    status: text("status", {
      enum: ["pending", "accepted", "declined", "canceled", "expired"],
    }).notNull(),
    expiresAt: text("expires_at").notNull(),
    resolvedAt: text("resolved_at"),
    createdAt: text("created_at").notNull(),
  },
  (table) => [
    index("ownership_handovers_org_status_idx").on(table.orgId, table.status),
  ],
);

export type OrganizationRow = typeof organizations.$inferSelect;
export type OwnershipHandoverRow = typeof ownershipHandovers.$inferSelect;

export async function setOrgOwner(
  orgId: OrgId,
  ownerId: UserId,
): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set({ ownerId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {

/**
 * Persisted ownership offers. An offer stays `pending` until it is accepted,
 * declined, withdrawn, or left to lapse by the clock.
 */
import { and, desc, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";
import type { OwnershipHandoverRow } from "@/server/db/schema/organizations";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
export const HANDOVER_TTL_MS = 7 * MS_PER_DAY;

function toHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId,
    status: row.status,
    expiresAt: row.expiresAt as IsoTimestamp,
    createdAt: row.createdAt as IsoTimestamp,
    resolvedAt: row.resolvedAt === null ? null : (row.resolvedAt as IsoTimestamp),
  };
}

export function handoverIsOpen(
  handover: OwnershipHandover,
  now: number = Date.now(),
): boolean {
  return handover.status === "pending" && Date.parse(handover.expiresAt) > now;
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: Date = new Date(),
): Promise<OwnershipHandover> {
  const created = toIsoTimestamp(createdAt);
  const expiresAt = toIsoTimestamp(new Date(createdAt.getTime() + HANDOVER_TTL_MS));

  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      resolvedAt: null,
      createdAt: created,
    })
    .returning()
    .get();

  return toHandover(row);
}

export async function listPendingHandovers(
  orgId: OrgId,
): Promise<readonly OwnershipHandover[]> {
  const rows = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending")),
    )
    .orderBy(desc(ownershipHandovers.createdAt))
    .all();

  return rows.map(toHandover);
}

export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: Exclude<OwnershipHandoverStatus, "pending" | "expired">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, id),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();

  return row ? toHandover(row) : null;
}

/** Withdraws every still-open offer that names `userId` on either side. */
export async function cancelOpenHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  resolvedAt: IsoTimestamp,
): Promise<void> {
  const pending = await listPendingHandovers(orgId);
  for (const handover of pending) {
    if (!handoverIsOpen(handover)) continue;
    if (handover.fromUserId !== userId && handover.toUserId !== userId) continue;
    await resolveHandover(orgId, handover.id, "canceled", resolvedAt);
  }
}

