input.new_string:
export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

function assertRecordedOwner(actor: Actor, ownerId: UserId): void {
  if (actor.userId === ownerId) return;
  throw new PermissionDeniedError("org:update", {
    allowed: false,
    action: "org:update",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

async function loadOrg(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

async function pendingState(orgId: OrgId): Promise<{
  open: OwnershipHandover | null;
  sawLapsed: boolean;
}> {
  const now = Date.now();
  const pending = await handoverRepo.listPendingHandovers(orgId);
  let open: OwnershipHandover | null = null;
  let sawLapsed = false;
  for (const handover of pending) {
    if (handoverRepo.handoverIsOpen(handover, now)) {
      if (open === null) open = handover;
    } else {
      sawLapsed = true;
    }
  }
  return { open, sawLapsed };
}

/**
 * Offers the recorded ownership to another active member. The offer lasts
 * seven days and is the only one that may be open for the workspace.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  const org = await loadOrg(actor, orgId);
  assertRecordedOwner(actor, org.ownerId);

  if (toUserId === org.ownerId || toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new (await import("./_support")).NotFoundError("Member", toUserId);
  }

  const { open } = await pendingState(orgId);
  if (open) throw new OwnershipHandoverError("pending_exists");

  const handover = await handoverRepo.insertHandover(orgId, actor.userId, toUserId);

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of this workspace",
    body: `${actor.userId} offered you ownership`,
    href: "/settings/members",
    actorId: actor.userId,
  });

  return handover;
}

async function requireOffered(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  await loadOrg(actor, orgId);
  const { open, sawLapsed } = await pendingState(orgId);
  if (!open) {
    throw new OwnershipHandoverError(sawLapsed ? "expired" : "nothing_pending");
  }
  if (open.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return open;
}

async function emitRoleChange(
  actor: Actor,
  before: Member,
  after: Member,
): Promise<void> {
  if (before.role === after.role) return;
  await emit("member.role_changed", {
    ...actorEnvelope(actor),
    memberId: after.id,
    from: before.role,
    to: after.role,
  });
}

/**
 * The offered member takes the recorded ownership. They gain the owner role
 * when they do not already hold it, and the previous recorded owner steps
 * down to admin when they still hold the owner role. The workspace keeps an
 * owner through the whole transition.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  const handover = await requireOffered(actor, orgId);
  const resolvedAt = toIsoTimestamp(new Date());

  const incoming = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );
  const outgoing = await memberRepo.findMember(orgId, handover.fromUserId);

  let promoted: Member | null = null;
  if (incoming.role !== "owner") {
    promoted = await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
  }

  const organization = await orgRepo.setOrgOwner(orgId, actor.userId);

  let demoted: Member | null = null;
  if (
    outgoing &&
    outgoing.userId !== actor.userId &&
    outgoing.role === "owner"
  ) {
    demoted = await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
  }

  const resolved = await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    resolvedAt,
  );
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");

  if (promoted) await emitRoleChange(actor, incoming, promoted);
  if (demoted && outgoing) await emitRoleChange(actor, outgoing, demoted);

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: actor.userId,
  });

  return organization;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const handover = await requireOffered(actor, orgId);
  const resolved = await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");
  return resolved;
}

/** The recorded owner withdraws the open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const org = await loadOrg(actor, orgId);
  assertRecordedOwner(actor, org.ownerId);

  const { open } = await pendingState(orgId);
  if (!open) throw new OwnershipHandoverError("nothing_pending");

  const resolved = await handoverRepo.resolveHandover(
    orgId,
    open.id,
    "canceled",
    toIsoTimestamp(new Date()),
  );
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");
  return resolved;
}

/** The open offer, if one can still be acted on. A lapsed offer is hidden. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  await loadOrg(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  const { open } = await pendingState(orgId);
  return open;
}

/**
 * A departure of either side ends the open offer. Called from member removal
 * so the offer cannot be accepted after one party has left.
 */
export async function withdrawHandoverIfPartyLeft(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  await handoverRepo.cancelOpenHandoversInvolving(
    orgId,
    userId,
    toIsoTimestamp(new Date()),
  );
}

const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

await withdrawHandoverIfPartyLeft(input.orgId, removed.userId);

await emit("member.removed", {

